//! `docs_url` / `redoc_url` / `spec_url` routes generated by `vespera!`.

use axum_example::create_app;
use serde_json::Value;
use testkit::{TestResponse, TestServer};
use vespera::axum::http::header::CONTENT_TYPE;
use vespera::docs::{REDOC_VERSION, SWAGGER_UI_VERSION, escape_json_for_script};

fn content_type(response: &TestResponse) -> &str {
    response.headers()[CONTENT_TYPE].to_str().unwrap()
}

async fn served_spec(server: &TestServer) -> String {
    let response = server.get("/openapi.json").await;
    response.assert_status_ok();
    assert_eq!(content_type(&response), "application/json");
    response.text()
}

#[tokio::test]
async fn spec_url_serves_the_generated_openapi_document() {
    let server = TestServer::new(create_app().await);
    let spec: Value = serde_json::from_str(&served_spec(&server).await).unwrap();

    let on_disk: Value = serde_json::from_str(include_str!("../openapi.json")).unwrap();
    assert_eq!(spec, on_disk);
    // Merged child app routes are part of the served document.
    assert!(
        spec["paths"]
            .as_object()
            .unwrap()
            .keys()
            .any(|p| p.starts_with("/third"))
    );
}

#[tokio::test]
async fn docs_pages_embed_the_escaped_spec_and_pinned_assets() {
    let server = TestServer::new(create_app().await);
    let spec = served_spec(&server).await;
    // The example spec contains `&` (query style examples), so escaping is
    // observable: the raw spec must NOT appear, the escaped one must.
    assert!(spec.contains('&'));
    let escaped = escape_json_for_script(&spec);

    for (path, pinned, script_elements) in [
        ("/docs", format!("swagger-ui-dist@{SWAGGER_UI_VERSION}/"), 3),
        ("/redoc", format!("redoc@{REDOC_VERSION}/"), 2),
    ] {
        let response = server.get(path).await;
        response.assert_status_ok();
        assert!(content_type(&response).starts_with("text/html"), "{path}");
        let html = response.text();

        assert!(html.contains(&escaped), "{path} embeds the escaped spec");
        assert!(!html.contains(&spec), "{path} must not embed the raw spec");
        assert!(html.contains(&pinned), "{path} pins {pinned}");
        assert!(html.contains("integrity=\"sha384-"), "{path} has SRI");
        assert!(html.contains("crossorigin=\"anonymous\""), "{path}");
        assert_eq!(html.matches("</script>").count(), script_elements, "{path}");
    }
}
